  const rel = path.relative(path.dirname(outPagePath), repoRoot);
  const src = (rel ? rel.split(path.sep).join('/') + '/' : '') + 'gate.js';
  return html.replace(/src="(?:\.\/|\.\.\/)*gate\.js"/g, `src="${src}"`);
