function changeStatus(btn, statusLabel, badgeClass, nextActionLabel) {
  // statusLabel is the localized text shown in the badge. All current
  // callers transition a row to the "verified" state, so the internal
  // data-status key (used by the sector/status/size filters above) and
  // the branch below are keyed off that fixed, locale-invariant string
  // rather than off statusLabel — comparing statusLabel to a literal
  // would silently stop matching once statusLabel is translated.
  const row = btn.closest('tr');
  const statusTd = row.querySelector('td:nth-child(5)');
  const actionTd = row.querySelector('td:nth-child(7)');

  statusTd.innerHTML = `<span class="badge ${badgeClass}">${statusLabel}</span>`;
  row.setAttribute('data-status', 'verified');

  actionTd.innerHTML = `<button class="btn btn-secondary" style="padding: 6px 12px; font-size:12px;" onclick="openModeration('suspend', '${row.querySelector('strong').textContent}')">${nextActionLabel}</button>`;
}

